// Python `remote_presets.py` dosyasından üretildi; elle değiştirme.

pub(crate) const API_GUARD: &str = r###"kubectl get --raw /readyz >/dev/null 2>&1 || { echo "== API SUNUCUSU YANIT VERMIYOR"; kubectl get --raw /readyz 2>&1 | tail -1 | cut -c1-200; echo "k3s: $(systemctl is-active k3s 2>/dev/null) | son baslangic: $(systemctl show k3s -p ActiveEnterTimestamp --value 2>/dev/null)"; journalctl -u k3s -n 6 --no-pager 2>/dev/null | cut -c1-200; exit 0; }; "###;
pub(crate) const PRESETS: &[(&str, &str, &str)] = &[
    ("k8s_health", r###"Küme/pod sağlık anlık görüntüsü: durum sayıları, hazır olmayan podlar, restart>3, uyarı event'leri, düğüm ve bellek kullanımı, boot/k3s başlangıç zamanı, limitsiz container sayısı"###, r###"echo "== POD DURUM"; kubectl get pods @@SCOPE@@ --no-headers | awk '{print $@@STATUS@@}' | sort | uniq -c; echo "== SORUNLU (Running/Completed disi veya hazir olmayan)"; kubectl get pods @@SCOPE@@ --no-headers | awk '{split($@@READY@@,r,"/")} ($@@STATUS@@!="Running" && $@@STATUS@@!="Completed") || ($@@STATUS@@=="Running" && r[1]!=r[2])'; echo "== RESTART>3"; kubectl get pods @@SCOPE@@ --no-headers | awk '$@@RESTARTS@@+0>3'; echo "== UYARI EVENT"; kubectl get events @@SCOPE@@ --field-selector type=Warning --sort-by=.lastTimestamp 2>/dev/null | tail -12 | cut -c1-220; echo "== DUGUM"; kubectl top nodes 2>&1; echo "boot: $(uptime -s 2>/dev/null) | k3s/kubelet: $(systemctl show k3s -p ActiveEnterTimestamp --value 2>/dev/null || systemctl show kubelet -p ActiveEnterTimestamp --value 2>/dev/null)"; echo "== BELLEK TOP"; kubectl top pods @@SCOPE@@ --sort-by=memory 2>&1 | head -8; echo "== LIMITSIZ CONTAINER"; kubectl get pods @@SCOPE@@ -o go-template='{{range .items}}{{range .spec.containers}}{{if not .resources.limits}}x{{"\n"}}{{end}}{{end}}{{end}}' | wc -l"###),
    ("k8s_resources", r###"Container başına CPU/bellek request ve limit tablosu (- = tanımsız)"###, r###"kubectl get pods @@SCOPE@@ -o go-template='{{range .items}}{{$n:=.metadata.namespace}}{{$p:=.metadata.name}}{{range .spec.containers}}{{$n}} {{$p}} {{.name}} {{with .resources.requests}}{{or .cpu "-"}} {{or .memory "-"}}{{else}}- -{{end}} {{with .resources.limits}}{{or .cpu "-"}} {{or .memory "-"}}{{else}}- -{{end}}{{"\n"}}{{end}}{{end}}' | (echo "NAMESPACE POD CONTAINER CPU_REQ MEM_REQ CPU_LIM MEM_LIM"; cat) | column -t"###),
];
